const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definitions
  const robinsonCrusoe = ee.Geometry.Point([-78.85, -33.64]).buffer(2000); // 2km buffer
  const santaClara = ee.Geometry.Point([-78.94, -33.70]).buffer(1500); // 1.5km buffer

  // 2. Time period
  const startDate = '2018-11-01';
  const endDate = '2018-11-30';

  // 3. Data Acquisition - Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  const s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2Clouds);

  // Check collection size
  const robinsonCol = s2Col.filterBounds(robinsonCrusoe);
  const santaCol = s2Col.filterBounds(santaClara);

  const robinsonSize = robinsonCol.size().getInfo();
  const santaSize = santaCol.size().getInfo();

  print(`Robinson Crusoe Images: ${robinsonSize}`);
  print(`Santa Clara Images: ${santaSize}`);

  if (robinsonSize === 0 || santaSize === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // 4. Processing - Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const robinsonMosaic = robinsonCol.map(addNDVI).median().select('NDVI');
  const santaMosaic = santaCol.map(addNDVI).median().select('NDVI');

  // 5. Calculate statistics and check valid pixels
  const robinsonStats = robinsonMosaic.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: robinsonCrusoe,
    scale: 100,
    maxPixels: 1e9
  });

  const santaStats = santaMosaic.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: santaClara,
    scale: 100,
    maxPixels: 1e9
  });

  const robinsonMean = robinsonStats.get('NDVI_mean').getInfo();
  const robinsonCount = robinsonStats.get('NDVI_count').getInfo();
  const santaMean = santaStats.get('NDVI_mean').getInfo();
  const santaCount = santaStats.get('NDVI_count').getInfo();

  print(`Robinson NDVI: ${robinsonMean?.toFixed(3)}, Pixels: ${robinsonCount}`);
  print(`Santa Clara NDVI: ${santaMean?.toFixed(3)}, Pixels: ${santaCount}`);

  // 6. Validation checks
  if (robinsonCount === 0 || santaCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  if (robinsonMean === null || santaMean === null || 
      isNaN(robinsonMean) || isNaN(santaMean) ||
      robinsonMean > 1 || robinsonMean < -1 ||
      santaMean > 1 || santaMean < -1) {
    print("<answer>C3</answer>");
    return;
  }

  // 7. Final comparison
  if (robinsonMean > santaMean) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
